mapper.select:
SELECT uc.user_card_id AS user_card_id, uc.member_id AS member_id, uc.card_id AS card_id, c.card_name AS card_name, b.benefit_id AS benefit_id, b.benefit_name AS benefit_name, b.limit_group_code AS limit_group_code, b.require_performance AS require_performance, b.performance_period AS performance_period, COALESCE(btl.tier_monthly_limit, b.monthly_limit) AS effective_monthly_limit, (COALESCE(rt.min_performance_amount, 0) > 0) AS month_performance_met, COALESCE(u.used_amount, 0) AS used_amount FROM user_card uc JOIN member m ON m.member_id = uc.member_id AND m.member_status = 'ACTIVE' JOIN card c ON c.card_id = uc.card_id JOIN benefit b ON b.card_id = uc.card_id AND b.is_active = 'Y' AND b.benefit_kind NOT IN ('GIFT', 'INSTALLMENT_FREE', 'RETROACTIVE') LEFT JOIN notification_setting ns ON ns.member_id = uc.member_id
LEFT JOIN user_card_monthly_state s_curr ON s_curr.user_card_id = uc.user_card_id AND s_curr.base_year_month = #{baseYearMonth}
LEFT JOIN user_card_monthly_state s_prev ON s_prev.user_card_id = uc.user_card_id AND s_prev.base_year_month = #{prevYearMonth}
LEFT JOIN performance_tier rt ON rt.card_id = uc.card_id AND rt.period_type = 'MONTH' AND rt.min_performance_amount = ( SELECT MAX(pt2.min_performance_amount) FROM performance_tier pt2 WHERE pt2.card_id = uc.card_id AND pt2.period_type = 'MONTH' AND pt2.min_performance_amount <= COALESCE( s_curr.prev_performance_amount, s_prev.current_performance_amount, 0 ) )
LEFT JOIN benefit_tier_limit btl ON btl.benefit_id = b.benefit_id AND btl.tier_id = rt.tier_id
LEFT JOIN user_benefit_usage u ON u.user_card_id = uc.user_card_id AND u.benefit_id = b.benefit_id AND u.base_year_month = #{baseYearMonth}
LEFT JOIN user_card_benefit_selection sel ON sel.user_card_id = uc.user_card_id AND sel.base_year_month = #{baseYearMonth} AND sel.option_group_code = b.option_group_code
WHERE uc.card_status = 'ACTIVE' AND COALESCE(ns.benefit_limit_enabled, 1) = 1 AND ( b.option_group_code IS NULL OR sel.selected_option_key = b.option_key )

SELECT uc.user_card_id AS user_card_id, uc.member_id AS member_id, uc.card_id AS card_id, c.card_name AS card_name, rt.shared_monthly_limit AS shared_monthly_limit, COALESCE(s_curr.shared_limit_used, 0) AS shared_limit_used FROM user_card uc JOIN member m ON m.member_id = uc.member_id AND m.member_status = 'ACTIVE' JOIN card c ON c.card_id = uc.card_id LEFT JOIN notification_setting ns ON ns.member_id = uc.member_id
LEFT JOIN user_card_monthly_state s_curr ON s_curr.user_card_id = uc.user_card_id AND s_curr.base_year_month = #{baseYearMonth}
LEFT JOIN user_card_monthly_state s_prev ON s_prev.user_card_id = uc.user_card_id AND s_prev.base_year_month = #{prevYearMonth}
LEFT JOIN performance_tier rt ON rt.card_id = uc.card_id AND rt.period_type = 'MONTH' AND rt.min_performance_amount = ( SELECT MAX(pt2.min_performance_amount) FROM performance_tier pt2 WHERE pt2.card_id = uc.card_id AND pt2.period_type = 'MONTH' AND pt2.min_performance_amount <= COALESCE( s_curr.prev_performance_amount, s_prev.current_performance_amount, 0 ) )
WHERE uc.card_status = 'ACTIVE' AND COALESCE(ns.benefit_limit_enabled, 1) = 1 AND rt.shared_monthly_limit IS NOT NULL AND rt.shared_monthly_limit > 0
